<?php
require __DIR__.'/includes/bootstrap.php';require_admin();require __DIR__.'/includes/layout.php';require_once __DIR__.'/includes/chauffeur_enquiries.php';
$error=null;
if($_SERVER['REQUEST_METHOD']==='POST'){
 verify_csrf();try{chauffeur_admin_update((string)($_POST['id']??''),(int)($_POST['revision']??0),(string)($_POST['status']??''),$_POST,(int)admin()['id']);flash('success','Solicitud actualizada. No se ha realizado ningún cobro.');redirect('driver-requests.php?id='.rawurlencode((string)$_POST['id']));}catch(DomainException $e){$error=$e->getMessage();}
}
$id=(string)($_GET['id']??'');$filter=(string)($_GET['status']??'');$states=chauffeur_states();$params=[];$where="JSON_UNQUOTE(JSON_EXTRACT(t.answers_json,'$.requestType'))='chauffeur'";
if($id!==''){$where.=' AND t.id=?';$params[]=$id;}
if(isset($states[$filter])){$where.=" AND JSON_UNQUOTE(JSON_EXTRACT(t.answers_json,'$.workflow'))=?";$params[]=$filter;}
$stmt=db()->prepare("SELECT t.*,CONCAT(u.first_name,' ',u.last_name) customer_name,u.email,u.phone FROM trip_requests t JOIN users u ON u.id=t.user_id WHERE $where ORDER BY t.updated_at DESC LIMIT 100");$stmt->execute($params);$rows=$stmt->fetchAll();
$services=db()->query("SELECT id,title_json,city FROM driver_services WHERE status='published' ORDER BY city")->fetchAll();
page_header('Solicitudes de chófer');?>
<section class="panel"><div class="panel-head"><div><p class="eyebrow">CHÓFER PERSONALIZADO</p><h2>Solicitudes y presupuestos</h2><p>Una solicitud no confirma un servicio. La aceptación del cliente y la confirmación de la agencia son pasos independientes.</p></div><a class="btn" href="reservations.php">Reservas confirmadas</a></div><div class="filters"><a href="driver-requests.php">Todas</a><?php foreach($states as $key=>$label):?><a href="?status=<?=e($key)?>" class="<?=$filter===$key?'active':''?>"><?=e($label)?></a><?php endforeach;?></div></section>
<?php if($error):?><div class="alert error" role="alert"><?=e($error)?></div><?php endif;?>
<?php foreach($rows as $row):$p=chauffeur_payload($row);$data=chauffeur_public($row);$request=$p['request'];$proposal=$p['proposal']??null;?>
<section class="panel"><div class="panel-head"><div><p class="eyebrow"><?=e($data['reference'])?> · <?=e($request['city'])?></p><h3><?=e($row['customer_name'])?></h3><span class="badge"><?=e($states[$p['workflow']]??$p['workflow'])?></span></div><a href="?id=<?=e($row['id'])?>">Abrir solicitud</a></div>
<div class="form-grid"><p><strong>Recogida</strong><br><?=e($request['pickup'])?></p><p><strong>Destino</strong><br><?=e($request['destination']?:'Servicio por horas')?></p><p><strong>Fecha (UTC)</strong><br><?=e($request['departure'])?></p><p><strong>Pasajeros / maletas</strong><br><?=(int)$request['passengers']?> / <?=(int)$request['bags']?></p><p><strong>Tipo / preferencia</strong><br><?=e($request['journey'].' · '.$request['vehiclePreference'])?></p><p><strong>Contacto</strong><br><?=e($row['phone'])?><br><?=e($row['email'])?></p></div>
<?php if(!empty($request['flight'])):?><p>Vuelo: <?=e($request['flight'])?></p><?php endif;?><?php if(!empty($request['returnDeparture'])):?><p>Vuelta (UTC): <?=e($request['returnDeparture'])?></p><?php endif;?><?php if(!empty($request['notes'])):?><p><?=nl2br(e($request['notes']))?></p><?php endif;?>
<?php if($proposal):?><div class="panel"><h4>Propuesta #<?=(int)$proposal['version']?> · <?=e(number_format($proposal['amountMinor']/100,2,',','.'))?> EUR</h4><p><?=nl2br(e($proposal['terms']))?></p><small>Vigente hasta <?=e($proposal['expiresAt'])?></small><?php if(isset($p['acceptance'])):?><p>✓ Aceptada por el cliente: <?=e($p['acceptance']['acceptedAt'])?></p><?php endif;?></div><?php endif;?>
<?php if(!empty($p['reservationId'])):?><a class="btn" href="reservations.php?id=<?=e($p['reservationId'])?>">Ver reserva confirmada</a><?php endif;?>
<?php if((admin()['role']??'reviewer')!=='reviewer'):?><form method="post" class="form-grid"><input type="hidden" name="_csrf" value="<?=e(csrf())?>"><input type="hidden" name="id" value="<?=e($row['id'])?>"><input type="hidden" name="revision" value="<?=(int)$row['revision']?>">
<label>Acción<select name="status" required><option value="">Selecciona una acción</option><?php foreach($states as $state=>$label):if(chauffeur_transition($p['workflow'],$state,false)):?><option value="<?=e($state)?>"><?=e($label)?></option><?php endif;endforeach;?></select></label>
<?php if(chauffeur_transition($p['workflow'],'proposal_sent',false)):?><label>Precio total EUR<input name="amount" inputmode="decimal" placeholder="150.00" value="<?=$proposal?e(number_format($proposal['amountMinor']/100,2,'.','')):''?>"></label><label>Vigencia (días)<input name="validDays" type="number" min="1" max="30" value="7"></label><label class="full">Condiciones, inclusiones y cancelación<textarea name="terms" rows="4" maxlength="5000"><?=e($proposal['terms']??'')?></textarea></label><?php endif;?>
<?php if(chauffeur_transition($p['workflow'],'confirmed',false)):?><label class="full">Servicio y vehículo para confirmar<select name="serviceId"><option value="">Selecciona un servicio publicado</option><?php foreach($services as $service):$title=json_decode($service['title_json'],true);?><option value="<?=e($service['id'])?>"><?=e($service['city'].' · '.($title['es']??$service['id']))?></option><?php endforeach;?></select><small>Se comprobarán la autorización profesional, el vehículo, su capacidad y la disponibilidad publicada. El pago permanece sin cobrar.</small></label><?php endif;?>
<button class="btn primary">Guardar cambio</button></form><?php endif;?></section>
<?php endforeach;?><?php if(!$rows):?><section class="panel"><p>No hay solicitudes de chófer con estos filtros.</p></section><?php endif;?>
<?php page_footer();
